{"intent": "Fuzz LRU/LRI against a reference model of all read paths and invariants", "command": "cd work/repo && cat > ../../fuzz_review.py <<'PY'
import random, sys, itertools
sys.path.insert(0, '.')
from boltons.cacheutils import LRI, LRU, DEFAULT_MAX_SIZE
from boltons.cacheutils import PREV, NEXT, KEY, VALUE, _MISSING

def model_set(ref, order, max_size, k, v):
    # dict semantics: overwrite keeps position, new key appended at end
    existed = k in ref
    ref[k] = v
    if existed:
        order.remove(k)
    order.insert(0, k)
    while len(order) > max_size:
        ev = order.pop()          # ll-oldest
        del ref[ev]               # may be anywhere in dict order

def check(cache, ref, order, max_size, ctx):
    errs = []
    d = dict(cache)
    if d != ref:
        errs.append('%s: dict(cache)=%r != ref=%r' % (ctx, d, ref))
    vals = list(cache.values())
    expect_vals = [ref[k] for k in ref]
    if vals != expect_vals:
        errs.append('%s: values()=%r != %r' % (ctx, vals, expect_vals))
    if list(cache.items()) != list(ref.items()):
        errs.append('%s: items() mismatch: %r vs %r' % (ctx, list(cache.items()), list(ref.items())))
    if list(cache.keys()) != list(ref.keys()):
        errs.append('%s: keys() mismatch' % ctx)
    lk = cache._link_lookup
    if set(lk) != set(ref):
        errs.append('%s: link_lookup keys %r != dict keys %r' % (ctx, sorted(map(repr,lk)), sorted(map(repr,ref))))
    for k in ref:
        if k not in lk:
            continue
        if lk[k][VALUE] != ref[k]:
            errs.append('%s: link value for %r is %r, dict says %r' % (ctx, k, lk[k][VALUE], ref[k]))
        if lk[k][KEY] != k:
            errs.append('%s: link KEY %r != %r' % (ctx, lk[k][KEY], k))
    # walk ll
    anchor = cache._anchor
    walk = []
    link = anchor[NEXT]
    prev = anchor
    count = 0
    while link is not anchor:
        if link[PREV] is not prev:
            errs.append('%s: broken prev link' % ctx); break
        walk.append(link[KEY])
        prev = link
        link = link[NEXT]
        count += 1
        if count > 1000:
            errs.append('%s: ll loop too long' % ctx); break
    if anchor[PREV] is not prev:
        errs.append('%s: anchor PREV does not point at newest (inv 2)' % ctx)
    if walk != order:
        errs.append('%s: ll order %r != model order %r' % (ctx, walk, order))
    if anchor[KEY] is not _MISSING or anchor[VALUE] is not _MISSING:
        errs.append('%s: anchor not reset' % ctx)
    if len(ref) > max_size:
        errs.append('%s: len %d > max_size %d' % (ctx, len(ref), max_size))
    if len(cache) != len(ref):
        errs.append('%s: len(cache)=%d != len(ref)=%d' % (ctx, len(cache), len(ref)))
    return errs

def run(seed, cls, max_size, use_on_miss=False):
    rnd = random.Random(seed)
    on_miss = (lambda k: 'om-%s' % k) if use_on_miss else None
    cache = cls(max_size=max_size, on_miss=on_miss)
    ref, order = {}, []
    errs = []
    hits = misses = soft = 0
    keys = list(range(6))
    for step in range(400):
        op = rnd.choice(['set','get','get','del','pop','pop','popdef','popitem','clear','update','setdefault','contains','eq','copy'])
        k = rnd.choice(keys)
        ctx = 'seed=%s step=%d op=%s k=%r' % (seed, step, op, k)
        try:
            if op == 'set':
                v = rnd.randint(0, 9)
                cache[k] = v
                model_set(ref, order, max_size, k, v)
            elif op == 'get':
                try:
                    got = cache[k]
                    if k in ref:
                        hits += 1
                        if got != ref[k]:
                            errs.append('%s: cache[%r]=%r != %r' % (ctx, k, got, ref[k]))
                        if cls is LRU:
                            order.remove(k); order.insert(0, k)
                    else:
                        errs.append('%s: unexpected hit for missing key' % ctx)
                except KeyError:
                    misses += 1
                    if k in ref:
                        errs.append('%s: unexpected miss' % ctx)
                    if on_miss:
                        if cls is LRU:
                            pass
                        # on_miss path: self[key] = on_miss(key)
                        # model it: cache already set it
                        model_set(ref, order, max_size, k, 'om-%s' % k)
            elif op == 'del':
                if k in ref:
                    del cache[k]
                    del ref[k]; order.remove(k)
                else:
                    try:
                        del cache[k]
                        errs.append('%s: del of missing key did not raise' % ctx)
                    except KeyError:
                        pass
            elif op == 'pop':
                if k in ref:
                    got = cache.pop(k)
                    if got != ref[k]:
                        errs.append('%s: pop returned %r != %r' % (ctx, got, ref[k]))
                    del ref[k]; order.remove(k)
                else:
                    try:
                        cache.pop(k)
                        errs.append('%s: pop of missing key did not raise' % ctx)
                    except KeyError:
                        pass
            elif op == 'popdef':
                dflt = 'D'
                got = cache.pop(k, dflt)
                if k in ref:
                    if got != ref[k]:
                        errs.append('%s: popdef returned %r != %r' % (ctx, got, ref[k]))
                    del ref[k]; order.remove(k)
                elif got != dflt:
                    errs.append('%s: popdef returned %r != default' % (ctx, got))
            elif op == 'popitem':
                if ref:
                    pk, pv = cache.popitem()
                    if ref[pk] != pv:
                        errs.append('%s: popitem %r=%r mismatch ref' % (ctx, pk, pv))
                    # dict.popitem pops last-inserted key
                    last_key = list(ref)[-1]
                    if pk != last_key:
                        errs.append('%s: popitem returned %r, dict-last is %r' % (ctx, pk, last_key))
                    del ref[pk]; order.remove(pk)
            elif op == 'clear':
                cache.clear(); ref.clear(); order[:] = []
            elif op == 'update':
                other = {kk: rnd.randint(0,9) for kk in rnd.sample(keys, rnd.randint(1,3))}
                cache.update(other)
                for kk, vv in other.items():
                    model_set(ref, order, max_size, kk, vv)
            elif op == 'setdefault':
                dv = rnd.randint(0,9)
                got = cache.setdefault(k, dv)
                if k in ref:
                    if got != ref[k]:
                        errs.append('%s: setdefault returned %r != %r' % (ctx, got, ref[k]))
                    if cls is LRU:
                        order.remove(k); order.insert(0, k)
                else:
                    if got != dv:
                        errs.append('%s: setdefault returned %r != %r' % (ctx, got, dv))
                    model_set(ref, order, max_size, k, dv)
                    soft += 1
            elif op == 'contains':
                if (k in cache) != (k in ref):
                    errs.append('%s: contains mismatch' % ctx)
            elif op == 'eq':
                if (cache == ref) != (dict(cache) == ref):
                    errs.append('%s: eq mismatch' % ctx)
            elif op == 'copy':
                c2 = cache.copy()
                if dict(c2) != ref:
                    errs.append('%s: copy dict mismatch' % ctx)
        except Exception as e:
            errs.append('%s: EXCEPTION %r' % (ctx, e))
            break
        errs.extend(check(cache, ref, order, max_size, ctx))
        if errs:
            return errs
    # counter sanity: total reads accounted for
    if (cache.hit_count, cache.miss_count, cache.soft_miss_count) != (hits, misses, soft):
        errs.append('counters: got %r, model %r' % ((cache.hit_count, cache.miss_count, cache.soft_miss_count), (hits, misses, soft)))
    return errs

total_fail = 0
for cls in (LRI, LRU):
    for max_size in (1, 2, 3, 5):
        for om in (False, True):
            for seed in range(60):
                errs = run(seed, cls, max_size, om)
                if errs:
                    total_fail += 1
                    print('FAIL', cls.__name__, max_size, 'on_miss=%s' % om, errs[0])
                    if total_fail > 15:
                        sys.exit(1)
print('done, failures:', total_fail)
