import random, re
from math import log
from humanize import naturalsize

suffixes = {"decimal": ("kB","MB","GB","TB","PB","EB","ZB","YB","RB","QB"),
            "binary": ("KiB","MiB","GiB","TiB","PiB","EiB","ZiB","YiB","RiB","QiB"),
            "gnu": "KMGTPEZYRQ"}

def check(v, binary, gnu, fmt="%.1f"):
    out = naturalsize(v, binary=binary, gnu=gnu, format=fmt)
    suffix = suffixes["gnu" if gnu else ("binary" if binary else "decimal")]
    base = 1024 if (gnu or binary) else 1000
    # parse output
    m = re.match(r"^(-?[\d.]+(?:e[+-]?\d+)?)\s*(\w+)$", out)
    if not m:
        return f"unparseable: {out!r}"
    num = float(m.group(1)); unit = m.group(2)
    if unit not in suffix:
        return f"unit {unit!r} not in suffixes (out={out!r})"
    exp = suffix.index(unit) + 1
    # displayed magnitude must be < base (except largest unit)
    if exp < len(suffix) and abs(num) >= base:
        return f"displayed |{num}| >= base for non-largest unit (out={out!r})"
    # implied bytes should be within rounding tolerance of v (for numeric formats)
    implied = abs(num) * base**exp
    if implied != 0:
        tol = 0.5 * 10**(-(fmt.count('f') and len(fmt.split('.')[1].rstrip('f')) or 0)) * base**exp if fmt.endswith('f') else None
        if tol and abs(implied - abs(v)) > tol * 1.0000001:
            return f"implied {implied} too far from {abs(v)} (out={out!r})"
    return None

random.seed(0)
problems = []
cases = []
# sweep around every boundary
for base in (1000, 1024):
    for k in range(1, 11):
        b = base**k
        for delta in range(-3, 4):
            for mult in (1, 3, 9, 40, 999):
                v = int(b*mult/1000) + delta
                if v > 0:
                    cases.append(v)
cases += [random.randint(1, 10**12) for _ in range(20000)]

for v in cases:
    for binary in (False, True):
        for gnu in (False, True):
            if gnu and binary: continue
            for fmt in ("%.1f", "%.0f", "%.3f", "%.2f"):
                r = check(v, binary, gnu, fmt)
                if r:
                    problems.append((v, binary, gnu, fmt, r))

# unique by problem type
seen = set()
for p in problems:
    key = p[4].split('(')[0]
    if key not in seen:
        seen.add(key)
        print(p)
print("total problems:", len(problems), "of", len(cases)*5*4)
