import re
from humanize import naturalsize

suffixes = {"decimal": ("kB","MB","GB","TB","PB","EB","ZB","YB","RB","QB"),
            "binary": ("KiB","MiB","GiB","TiB","PiB","EiB","ZiB","YiB","RiB","QiB"),
            "gnu": "KMGTPEZYRQ"}

def parse(out, gnu):
    m = re.match(r"^(-?[\d.]+(?:e[+-]?\d+)?)\s*([A-Za-z]+)$", out)
    if not m: return None
    num = float(m.group(1)); unit = m.group(2)
    suffix = suffixes["gnu" if gnu else None] if False else (suffixes["gnu"] if gnu else None)
    return num, unit

def check(v, mode, fmt):
    binary = mode == "binary"; gnu = mode == "gnu"
    out = naturalsize(v, binary=binary, gnu=gnu, format=fmt)
    suffix = suffixes["gnu" if gnu else ("binary" if binary else "decimal")]
    base = 1024 if (gnu or binary) else 1000
    m = re.match(r"^(-?[\d.]+(?:e[+-]?\d+)?)\s*([A-Za-z]+)$", out)
    if not m: return f"unparseable: {out!r} for v={v!r}"
    num = float(m.group(1)); unit = m.group(2)
    if unit not in suffix:
        return f"unit {unit!r} for v={v!r} fmt={fmt} out={out!r}"
    exp = suffix.index(unit) + 1
    probs = []
    if exp < len(suffix) and abs(num) >= base:
        probs.append(f"DISPLAY>=base: v={v!r} fmt={fmt} mode={mode} out={out!r}")
    # self-consistency: output for implied value must equal output
    implied = num * base**exp
    try:
        out2 = naturalsize(implied, binary=binary, gnu=gnu, format=fmt)
        if out2 != out:
            probs.append(f"INCONSISTENT with rounded value: v={v!r} fmt={fmt} mode={mode} out={out!r} implied={implied!r} -> {out2!r}")
    except Exception as e:
        probs.append(f"implied raise: v={v!r} implied={implied!r} {e!r}")
    return "; ".join(probs) if probs else None

fmts = ["%.1f", "%.0f", "%.2f", "%.3f", "%.5f", "%.10f", "%d", "%i", "%g", "%.3g", "%.1e", "%.0e", "%+.1f", "%08.1f", "%.1f", "%.4f"]
