const parse = require('./parse.js')

const diff = (version1, version2) => {
  const v1 = parse(version1, null, true)
  const v2 = parse(version2, null, true)
  const comparison = v1.compare(v2)

  if (comparison === 0) {
    return null
  }

  const v1Higher = comparison > 0
  const highVersion = v1Higher ? v1 : v2
  const lowVersion = v1Higher ? v2 : v1
  const highHasPre = !!highVersion.prerelease.length
  const lowHasPre = !!lowVersion.prerelease.length

  if (lowHasPre && !highHasPre) {
    // Going from prerelease -> no prerelease requires some special casing.

    const sameMain =
      v1.major === v2.major &&
      v1.minor === v2.minor &&
      v1.patch === v2.patch

    if (sameMain) {
      // The prerelease of the low version stands in for a release bump that
      // never happened, so the diff is the bump that is still missing from
      // the low version:
      // 1.0.0-1 -> 1.0.0: minor and patch are zero, so it is a major bump
      // 0.1.0-1 -> 0.1.0: only the patch is zero, so it is a minor bump
      // 1.0.1-1 -> 1.0.1: nothing is zero, so it is a patch bump
      if (lowVersion.minor || lowVersion.patch) {
        return 'patch'
      }
      if (lowVersion.major) {
        return 'minor'
      }
      // 0.0.0-x: bumping major, minor or patch all look the same
      return 'major'
    }

    // The main versions differ: the highest changed level is the candidate.
    const level =
      v1.major !== v2.major ? 'major'
        : v1.minor !== v2.minor ? 'minor'
          : 'patch'
    if (level === 'major') {
      return 'major'
    }

    // For minor/patch, check whether the prerelease could plausibly have
    // been released as the high version.  The release right before the high
    // version drops the changed level (3.5.2 -> 3.4.9), so if the low
    // version is not below that, releasing its prerelease as the high
    // version would have skipped versions, and the real jump must be the
    // next level down. e.g. 1.0.1-1 -> 1.0.1 is only a patch, and
    // 0.0.2-1 -> 0.1.0 is only a minor, because 0.0.9 would exist anyway.
    const lower = parse(highVersion.version).inc(level)
    if (lowVersion.compare(lower) >= 0) {
      return 'patch'
    }

    return level
  }

  // add the `pre` prefix if we are going to a prerelease version
  const prefix = highHasPre ? 'pre' : ''

  if (v1.major !== v2.major) {
    return prefix + 'major'
  }

  if (v1.minor !== v2.minor) {
    return prefix + 'minor'
  }

  if (v1.patch !== v2.patch) {
    return prefix + 'patch'
  }

  // high and low are preleases
  return 'prerelease'
}

module.exports = diff
