    base = IndexedSet(items)
    s1 = IndexedSet(items); s1.remove('c')
    yield ('remove', s1, [x for x in items if x != 'c'])
    s2 = IndexedSet(items); s2.discard('c'); s2.discard('a'); s2.discard('j')
    rem = [x for x in items if x not in ('c','a','j')]
    yield ('discard3', s2, rem)
    s3 = IndexedSet(items); s3.remove('e'); s3.pop(0); s3.remove('j')
    rem = [x for x in items if x not in ('e','a','j')]
    yield ('mix', s3, rem)
    s4 = IndexedSet(items)
    for x in 'bdfhj': s4.remove(x)
    rem = [x for x in items if x not in 'bdfhj']
    yield ('many', s4, rem)
    # empty-ish
    s5 = IndexedSet(items)
    for x in items[:]: s5.remove(x)
    yield ('empty', s5, [])
    # single survivor
    s6 = IndexedSet(items)
    for x in items[:]:
        if x != 'f': s6.remove(x)
    yield ('single', s6, ['f'])

bounds = [None, -100, -10, -5, -3, -1, 0, 1, 3, 5, 9, 10, 100, 10**20]
steps = [None, -7, -3, -1, 1, 2, 3, 7]

for name, s, expected in removal_sets():
    fresh = IndexedSet(expected)
    lst = expected
    # 1) removed-set slice vs fresh-set slice (all bounds)
    for a, b, c in product(bounds, bounds, steps):
        sl = slice(a, b, c)
        try:
            got = list(s[sl])
        except Exception as e:
            got = ('EXC', type(e).__name__, str(e))
        try:
            want = list(fresh[sl])
        except Exception as e:
            want = ('EXC', type(e).__name__, str(e))
        if got != want:
            fail.append((name, 'removed-vs-fresh', (a,b,c), got, want))
    # 2) forward slices vs list(s)[...]
    for a, b, c in product(bounds, bounds, [None, 1, 2, 3, 7]):
        sl = slice(a, b, c)
        try:
            got = list(s[sl])
        except Exception as e:
            got = ('EXC', type(e).__name__, str(e))
        want = lst[a:b:c]
        if got != want:
            fail.append((name, 'vs-list', (a,b,c), got, want))
    # 3) indexing vs list
    for i in range(-len(lst)-3, len(lst)+3):
        try: got = s[i]
        except Exception as e: got = ('EXC', type(e).__name__, str(e))
        if i < -len(lst) or i >= len(lst):
            want = ('EXC', 'IndexError', 'x')
        else:
            want = lst[i]
        if isinstance(want, tuple) and want[0]=='EXC':
            if not (isinstance(got, tuple) and got[1]=='IndexError'):
                fail.append((name, 'index-should-raise', i, got, want))
        elif got != want:
