        assert sorted(cache.items()) == sorted(val.items()), stage
        assert sorted(cache.keys()) == sorted(val.keys()), stage
        assert sorted(cache.values()) == sorted(val.values()), stage
        assert len(cache) == len(val), stage
        assert list(cache) == dorder, (stage, list(cache), dorder)
        # internal link order
        ll = [k for (k, v) in cache._get_flattened_ll()[1:-1]]
        assert ll == lorder, (stage, ll, lorder)
        for k in cache:
