    if dict(c) != model: errs.append(('dict', dict(c), model))
    if {k:c[k] for k in c} != model: errs.append(('getitem', {k:c[k] for k in c}, model))
    if dict(c.items()) != model: errs.append(('items', dict(c.items()), model))
    if sorted(c.values()) != sorted(model.values()): errs.append(('values', list(c.values()), list(model.values())))
    if set(c.keys()) != set(model.keys()): errs.append(('keys', set(c.keys()), set(model.keys())))
    if len(c) != len(model): errs.append(('len', len(c), len(model)))
    if set(c._link_lookup) != set(model): errs.append(('link_lookup', set(c._link_lookup), set(model)))
    # ll walk
