        keys = [k for k,v in flat if k is not None and v is not None]
        # anchor excluded: _get_flattened_ll includes anchor? check
    except Exception as e:
        errs.append(('ll', type(e).__name__))
    if errs:
        print('FAIL', label, errs)
        return False
    return True

