    for step in range(30):
        op = random.choice(ops)
        k = random.choice('abcde')
        try:
            if op=='set':
                v = random.randint(0,9); c[k]=v; model[k]=v
            elif op=='del':
                if k in model: del c[k]; del model[k]
                else:
                    try: del c[k]
                    except KeyError: pass
            elif op=='get':
                c.get(k); model.get(k)
            elif op=='pop':
                d = random.randint(0,9)
                r = c.pop(k, d); mr = model.pop(k, d)
                if r != mr: print('pop mismatch', r, mr); bad+=1
            elif op=='popitem':
                if len(model):
                    it = c.popitem(); mk, mv = model.popitem() if False else (None,None)
                    # dict popitem LIFO; both same class dict so should match
                    if it[0] not in model: print('popitem key not in model'); bad+=1
                else:
                    try: c.popitem()
                    except KeyError: pass
            elif op=='clear':
                c.clear(); model.clear()
            elif op=='update':
                d = {random.choice('abcde'): random.randint(0,9) for _ in range(random.randint(1,3))}
                c.update(d); model.update(d)
            elif op=='ior':
                d = {random.choice('abcde'): random.randint(0,9) for _ in range(random.randint(1,3))}
                try:
                    c |= d
                except Exception as e:
                    print('ior raised', e)
                model.update(d)  # dict.__ior__ semantics? but with capacity limit...
            elif op=='setdefault':
                v = random.randint(0,9)
                r = c.setdefault(k, v); mr = model.setdefault(k, v)
                if r != mr: print('setdefault mismatch', r, mr); bad+=1
            elif op=='copy':
