# jinja2's filesizeformat reference implementation
def jinja_fs(value, binary=False):
    base = 1024 if binary else 1000
    for x in ("bytes","KiB","MiB","GiB","TiB","PiB","EiB"):
        if value < base:
            return "%d %s" % (value, x) if x=="bytes" else "%.1f %s" % (value, x)
        value /= base
    return "%.1f EiB" % value

