// Simulate OLD order (numeric first) vs NEW order (nonnumeric first) to find behavior diffs
const { src, t, safeRe } = require('./internal/re');

function testWithOrder(order) {
  // build a regex with given order
  const nonnum = src[t.NONNUMERICIDENTIFIER];
  const num = src[t.NUMERICIDENTIFIER];
  const ident = order === 'new' ? '(?:'+nonnum+'|'+num+')' : '(?:'+num+'|'+nonnum+')';
  const pre = '(?:-('+ident+'(?:\\\\.'+ident+'))*)';
  const coerceFull = src[t.COERCEPLAIN] + pre + '(?:' + src[t.BUILD] + ')?' + '(?:\$|[^\\\\d])';
  return new RegExp(coerceFull);
}
const oldR = testWithOrder('old');
const newR = testWithOrder('new');
const cases = ['1.2.3-01', '1.2.3-0', '1.2.3-7f3c', '1.2.3-nightly.7f3c', '1.2.3-rc.1', '1.2.3-4821.9e1d', '1.2.3-00.44', '1.2.3-1a.2b', '1.2.3-abc', '1.2.3-123abc'];
for (const c of cases) {
  const om = c.match(oldR);
  const nm = c.match(newR);
  const o = om ? om[5] : null;
  const n = nm ? nm[5] : null;
  console.log(c, '| old:', o, '| new:', n, o !== n ? '  <-- DIFF' : '');
}
""}

